//! 🧪️ Native ledger leases return the same authored rows and factory after exact funded closure.
use super::*;
use semio_framework_job::*;
use semio_framework_value::{ArtifactOwnedValueRetirementFactory,ErasedSnapshotRetirement,RetainedOwnedProjection,RetirementDemand,RetainedCloneGrant,RetainedCloneProgress,RetainedCloneStep,ValueError,retirement::RetireOwned};
use std::{sync::Arc,marker::PhantomData};
#[global_allocator]static HEAP:semio_framework_trace::HeapWitness=semio_framework_trace::HeapWitness;
const TURN:RetainedCloneGrant=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:4096,maximum_capacity_bytes:4096,maximum_release_bytes:262144,maximum_depth:4096};
#[derive(semio_framework_value::FactoryPayloadRetirement)]struct Factory<T>(PhantomData<fn()->T>);
impl<T:RetireOwned> ArtifactOwnedValueRetirementFactory<T> for Factory<T>{fn retirement_birth_bytes(&self,_:&T)->usize{semio_framework_value::retirement::controlled::controlled_retirement_birth_bytes::<T>()}fn retire_owned(&self,value:T,grant:RetainedCloneGrant)->Result<(Box<dyn ErasedSnapshotRetirement>,RetainedCloneProgress),(ValueError,T)>{semio_framework_value::retirement::controlled::admit_typed_controlled_retirement(value,grant).map(|(owner,p)|(owner as Box<dyn ErasedSnapshotRetirement>,p))}}
fn original()->OriginalJobFixtureCaller{OriginalJobFixtureCaller::admit(OperationId(8610),Generation(51),RetainedCloneGrant{maximum_items:1<<24,maximum_copy_bytes:1<<24,maximum_capacity_bytes:1<<24,maximum_release_bytes:1<<24,maximum_depth:4096},default_now_us,u64::MAX,1<<24)}
fn turn<T>(caller:&mut OriginalJobFixtureCaller,g:RetainedCloneGrant,run:impl FnOnce(&mut StepContext<'_>)->Result<T,OriginalTurnFailure>)->T{let(result,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||caller.turn(g,run));let p=caller.receipt();assert_eq!((heap.requested_bytes,heap.released_bytes),(p.retained_capacity_bytes,p.released_bytes));result.unwrap()}
fn paid(caller:&mut OriginalJobFixtureCaller,g:RetainedCloneGrant,d:RetirementDemand,run:impl FnOnce(RetainedCloneGrant)->Result<RetainedCloneStep,ValueError>)->RetainedCloneProgress{turn(caller,g,|cx|cx.with_original_retirement(|cx|{let mut result=Default::default();close_original_retained_step(cx,d,|grant|{let step=run(grant)?;result=step.progress();Ok(step)})?;Ok(result)}))}
fn denied(d:RetirementDemand)->Vec<RetainedCloneGrant>{let mut values=vec![RetainedCloneGrant{maximum_items:0,..TURN}];if d.copy_bytes>0{values.push(RetainedCloneGrant{maximum_copy_bytes:d.copy_bytes-1,..TURN})}if d.capacity_bytes>0{values.push(RetainedCloneGrant{maximum_capacity_bytes:d.capacity_bytes-1,..TURN})}if d.release_bytes>0{values.push(RetainedCloneGrant{maximum_release_bytes:d.release_bytes-1,..TURN})}if d.depth>0{values.push(RetainedCloneGrant{maximum_depth:d.depth-1,..TURN})}values}
macro_rules! read_law{($ledger:expr,$state:ty,$blocked:expr)=>{{for cut in 0..4{let mut ledger=$ledger;let mut caller=original();let key=ledger.retained_read_key("source").unwrap();let revision=ledger.source_revision();let pointer=ledger.open("source").unwrap().entries.as_ptr();let factory:Arc<dyn ArtifactOwnedValueRetirementFactory<$state>>=Arc::new(Factory::<$state>(PhantomData));let mut ready=false;for _ in 0..cut{let d=ledger.retained_read_demands("source",key).unwrap();for g in denied(d){assert_eq!(paid(&mut caller,g,d,|grant|ledger.advance_retained_read("source",key,&factory,grant)),Default::default());}paid(&mut caller,TURN,d,|grant|{let step=ledger.advance_retained_read("source",key,&factory,grant)?;ready=matches!(step,RetainedCloneStep::Complete(_));Ok(step)});if ready{break}}
let mut projection=None;if ready{let d=RetainedOwnedProjection::<$state>::constructor_demand();paid(&mut caller,TURN,d,|grant|{let(original,p)=ledger.retain_original_read("source",key,grant)?;projection=Some(original);Ok(RetainedCloneStep::Progress(p))});assert_eq!(projection.as_ref().unwrap().borrow().unwrap().get().entries.as_ptr(),pointer);assert!($blocked(&mut ledger));assert_eq!(ledger.source_revision(),revision);}
caller.cancel().cancel_now();if let Some(projection)=projection.as_mut(){for index in 0..65536{if projection.terminal_is_empty(){break}let d=projection.close_demand(4096).unwrap();for g in denied(d){assert_eq!(paid(&mut caller,g,d,|grant|projection.close_step(grant)),Default::default());}paid(&mut caller,TURN,d,|grant|projection.close_step(grant));assert!(index<65535)}}drop(projection);
let mut returned=None;for index in 0..65536{if !ledger.retained_read_pending("source"){break}let d=ledger.retained_read_return_demands("source",key,4096).unwrap();for g in denied(d){assert_eq!(paid(&mut caller,g,d,|grant|ledger.return_retained_read("source",key,&mut returned,grant)),Default::default());}paid(&mut caller,TURN,d,|grant|ledger.return_retained_read("source",key,&mut returned,grant));assert!(index<65535)}assert_eq!(ledger.source_revision(),revision);assert_eq!(ledger.open("source").unwrap().entries.as_ptr(),pointer);if let Some(returned)=returned{assert!(Arc::ptr_eq(&factory,&returned));}caller.retire(TURN);}}}}
fn scrub()->ScrubLedger<u64>{let mut ledger=ScrubLedger::default();let mut input=Some(ScrubInput::Tick{gesture:"press".into(),leaves:(0..8197).collect()});ledger.send("source","test#press",&ActorId("native-source".into()),"base",&mut input,HybridLogicalTimestamp{actor:0,physical_ms:10,logical:0}).unwrap();ledger}
fn typing()->TypingLedger<u64>{let mut ledger=TypingLedger::default();ledger.send("source","test#typing",&ActorId("native-source".into()),TypingInput::Edit{buffer:"text".into(),leaves:(0..8197).collect()},|_,next|TypingFold::Net(next.to_vec()),HybridLogicalTimestamp{actor:0,physical_ms:10,logical:0}).unwrap();ledger}
fn gesture()->GestureLedger<u64>{let mut ledger=GestureLedger::default();ledger.settle("source",Some(GestureState{states:vec!["dragging".into()],verb:"test#gesture".into(),press:"press".into(),authoring_seed:"native-source".into(),base_revision:"base".into(),transaction:TransactionRef{id:"tx-0000000000000001".into(),tool:"test#gesture".into()},entries:(0..8197).map(|value|(value.to_string(),value)).collect(),context:protocol::DslValue::Null})).unwrap();ledger}
#[test]fn original_scrub_read_preserves_original_rows_and_issuer(){read_law!(scrub(),ScrubState<u64>,|ledger:&mut ScrubLedger<u64>|{let mut input=Some(ScrubInput::Commit{gesture:"press".into(),leaves:vec![]});ledger.send("source","test#press",&ActorId("native-source".into()),"base",&mut input,HybridLogicalTimestamp{actor:0,physical_ms:10,logical:1}).is_err()&&input.is_some()});}
#[test]fn original_typing_read_preserves_original_rows_and_issuer(){read_law!(typing(),TypingState<u64>,|ledger:&mut TypingLedger<u64>|ledger.commit("source",TypingCommit::Enter,HybridLogicalTimestamp{actor:0,physical_ms:10,logical:1}).is_err());}
#[test]fn original_gesture_read_preserves_original_rows_and_issuer(){read_law!(gesture(),GestureState<u64>,|ledger:&mut GestureLedger<u64>|ledger.settle("source",None).is_err());}

fn turn_native<T>(caller:&mut OriginalJobFixtureCaller,decoder:&mut OriginalJobDecodeOwner,g:RetainedCloneGrant,run:impl FnOnce(&mut StepContext<'_>)->Result<T,OriginalTurnFailure>)->T{let(result,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||caller.turn_with_decoder(g,decoder,run));let p=caller.receipt();assert_eq!((heap.requested_bytes,heap.released_bytes),(p.retained_capacity_bytes,p.released_bytes));result.unwrap()}
macro_rules! transfer_law{($ledger:expr,$state:ty)=>{{let mut ledger=$ledger;let mut caller=original();let mut decoder=OriginalJobDecodeOwner::empty();let key=ledger.resident_key("source").unwrap();let pointer=ledger.open("source").unwrap().entries.as_ptr();let revision=ledger.source_revision();let mut output=None;let d=<$state>::original_transfer_demands();for denied in denied(d){turn_native(&mut caller,&mut decoder,denied,|cx|{let grant=cx.retained_grant();let mut done=None;admit_original_construction(cx,&mut done,OriginalConstructionDemand{items:1,copy_bytes:d.copy_bytes,capacity_bytes:d.capacity_bytes,release_bytes:d.release_bytes,depth:d.depth},|_|{let p=ledger.withdraw_original("source",key,&mut output,grant)?.unwrap();Ok(((),p))})?;assert!(done.is_none());Ok(())});assert!(output.is_none());assert_eq!(ledger.source_revision(),revision);assert_eq!(ledger.open("source").unwrap().entries.as_ptr(),pointer);}
turn_native(&mut caller,&mut decoder,TURN,|cx|{let grant=cx.retained_grant();let mut done=None;admit_original_construction(cx,&mut done,OriginalConstructionDemand{items:1,copy_bytes:d.copy_bytes,capacity_bytes:d.capacity_bytes,release_bytes:d.release_bytes,depth:d.depth},|_|{let p=ledger.withdraw_original("source",key,&mut output,grant)?.unwrap();Ok(((),p))})?;assert!(done.is_some());Ok(())});assert!(ledger.is_empty());assert!(ledger.open("source").is_none());assert_eq!(ledger.provisional().count(),0);assert_eq!(output.as_ref().unwrap().entries.as_ptr(),pointer);assert_ne!(ledger.source_revision(),revision);let vacant=ledger.resident_key("source").unwrap();assert_ne!(vacant,key);
for denied in denied(d){turn_native(&mut caller,&mut decoder,denied,|cx|{let grant=cx.retained_grant();let mut done=None;admit_original_construction(cx,&mut done,OriginalConstructionDemand{items:1,copy_bytes:d.copy_bytes,capacity_bytes:d.capacity_bytes,release_bytes:d.release_bytes,depth:d.depth},|_|{let p=ledger.install_resident_original("source",vacant,&mut output,grant)?.unwrap();Ok(((),p))})?;assert!(done.is_none());Ok(())});assert!(ledger.is_empty());assert_eq!(output.as_ref().unwrap().entries.as_ptr(),pointer);}
turn_native(&mut caller,&mut decoder,TURN,|cx|{let grant=cx.retained_grant();let mut done=None;admit_original_construction(cx,&mut done,OriginalConstructionDemand{items:1,copy_bytes:d.copy_bytes,capacity_bytes:d.capacity_bytes,release_bytes:d.release_bytes,depth:d.depth},|_|{let p=ledger.install_resident_original("source",vacant,&mut output,grant)?.unwrap();Ok(((),p))})?;assert!(done.is_some());Ok(())});assert!(output.is_none());assert!(!ledger.is_empty());assert_eq!(ledger.open("source").unwrap().entries.as_ptr(),pointer);
let key=ledger.resident_key("source").unwrap();turn_native(&mut caller,&mut decoder,TURN,|cx|{let grant=cx.retained_grant();let mut done=None;admit_original_construction(cx,&mut done,OriginalConstructionDemand{items:1,copy_bytes:d.copy_bytes,capacity_bytes:d.capacity_bytes,release_bytes:d.release_bytes,depth:d.depth},|_|{let p=ledger.withdraw_original("source",key,&mut output,grant)?.unwrap();Ok(((),p))})?;Ok(())});let mut owner=semio_framework_value::retirement::controlled::ControlledRetirement::new(output.take().unwrap()).map_err(|(error,_)|error).unwrap();for index in 0..1048576{if owner.terminal_is_empty(){break}let d=owner.select(4096).unwrap().demands();let event=RetainedCloneGrant{maximum_release_bytes:d.release_bytes,..TURN};assert!(semio_framework_value::retained_clone::retained_clone_grant_admits(event,d),"actual original ledger row close demands {d:?}");for denied in denied(d){let selected=owner.select(4096).unwrap();assert_eq!(selected.demands(),d);turn_native(&mut caller,&mut decoder,denied,|cx|cx.with_original_retirement(|cx|{close_original_retained_step(cx,d,|grant|selected.step(grant))?;Ok(())}));assert_eq!(caller.receipt(),Default::default());}let selected=owner.select(4096).unwrap();turn_native(&mut caller,&mut decoder,event,|cx|cx.with_original_retirement(|cx|{close_original_retained_step(cx,d,|grant|selected.step(grant))?;Ok(())}));assert!(index<1048575)}assert!(owner.terminal_is_empty());assert!(ledger.is_empty());while !decoder.terminal_is_empty(){turn(&mut caller,TURN,|cx|cx.with_original_retirement(|cx|{let d=decoder.retirement_demands(4096)?;close_original_retained_step(cx,d,|grant|decoder.close_step(grant))?;Ok(())}));}caller.retire(TURN);}}}
#[test]fn original_scrub_transfer_preserves_resident_and_entries(){transfer_law!(scrub(),ScrubLedger<u64>);}
#[test]fn original_gesture_transfer_preserves_resident_and_entries(){transfer_law!(gesture(),GestureLedger<u64>);}
#[test]fn original_typing_transfer_preserves_resident_and_entries(){transfer_law!(typing(),TypingLedger<u64>);}
